 CompanyProjectNearbyPlaceCommand? NearbyPlace(ProjectNearbyPlaceRequest request){var category=request.Category?.Trim();var name=request.Name?.Trim();if(string.IsNullOrWhiteSpace(category)||category.Length>100||string.IsNullOrWhiteSpace(name)||name.Length>200||request.DistanceMeters is <0||request.TravelMinutes is <0||request.Latitude is < -90 or > 90||request.Longitude is < -180 or > 180||!ScaleAtMost(request.DistanceMeters,2)||!ScaleAtMost(request.Latitude,6)||!ScaleAtMost(request.Longitude,6))ModelState.AddModelError("nearbyPlace","Invalid nearby place.");Row(request.RowVersion);return new(category??string.Empty,name??string.Empty,request.DistanceMeters,request.TravelMinutes,request.Latitude,request.Longitude);}
