 CompanyProjectQuery? Query(CompanyProjectDirectoryRequest r){if(r.PageNumber is <1 or >10000)ModelState.AddModelError("pageNumber","Invalid page number.");if(r.PageSize is <1 or >50)ModelState.AddModelError("pageSize","Invalid page size.");var search=r.Search?.Trim();if(r.Search!=null&&(string.IsNullOrWhiteSpace(search)||search.Length>100))ModelState.AddModelError("search","Invalid search.");Enum<ProjectStatus>(r.Status,out var s);Enum<ProjectDeliveryStatus>(r.DeliveryStatus,out var d);if((r.Status!=null&&s==null)||(r.DeliveryStatus!=null&&d==null))ModelState.AddModelError("filter","Invalid status.");return new(r.PageNumber,r.PageSize,search,s,d,r.LocationId);} CompanyProjectCommand? Command(CompanyProjectRequest r,bool rv){var n=r.Name?.Trim();var slug=r.Slug?.Trim();var desc=string.IsNullOrWhiteSpace(r.Description)?null:r.Description.Trim();Enum<ProjectDeliveryStatus>(r.DeliveryStatus,out var d);if(string.IsNullOrWhiteSpace(n)||n.Length>200||string.IsNullOrWhiteSpace(slug)||slug.Length>200||slug!=slug.ToLowerInvariant()||!Slug.IsMatch(slug)||desc?.Length>4000||r.LocationId==Guid.Empty||d==null)ModelState.AddModelError("project","Invalid project.");var v=rv?Row(r.RowVersion):null;return new(n??"",slug??"",desc,r.LocationId,d??default,r.ExpectedDeliveryDate,v);} byte[]? Row(string? x){try{var b=string.IsNullOrWhiteSpace(x)?null:Convert.FromBase64String(x);if(b?.Length==8)return b;}catch(FormatException){}ModelState.AddModelError("rowVersion","Invalid row version.");return null;} static bool Enum<T>(string? x,out T? v)where T:struct,Enum{if(x==null){v=null;return true;}if(System.Enum.TryParse<T>(x,false,out var z)&&System.Enum.IsDefined(z)&&string.Equals(x,z.ToString(),StringComparison.Ordinal)){v=z;return true;}v=null;return false;} bool UserId(out Guid u)=>Guid.TryParse(User.FindFirst("sub")?.Value,out u)&&u!=Guid.Empty; ObjectResult ProjectNotFound()=>Problem(statusCode:404,title:"Project not found.");ObjectResult ProjectConflict()=>Problem(statusCode:409,title:"